<script setup lang="ts">
import {computed,reactive,ref,watch,onBeforeUnmount,nextTick} from 'vue'
import {useRoute,useRouter,onBeforeRouteLeave} from 'vue-router'
import axios from 'axios'
import {api,errorMessage,idempotencyKey,type Page} from '../../api/http'
import type {EbrDetail,EbrSummary} from '../ebr/types'
import {useAuthStore} from '../../stores/auth'
import {states,blankRoute,clone,type Package,type Product,type ApplicableProduct,type RouteDefinition,type Rule} from './model'

import {selectAccessibility as vSelectAccessibility} from '../ebr/selectAccessibility'
import CompletionRuleEditor from './CompletionRuleEditor.vue'
import OperationItemDialog from './OperationItemDialog.vue'
import type {Operation,Parameter,IpcDefinition} from './model'
const route=useRoute(),router=useRouter(),auth=useAuthStore(),pkg=ref<Package|null>(null),v=computed(()=>pkg.value?.currentDefinition),create=computed(()=>route.meta.mode==='create'),editing=computed(()=>route.meta.mode==='edit'),editable=computed(()=>editing.value&&pkg.value?.status==='ACTIVE'&&auth.can('process:package:edit')&&!busy.value)
const createForm=reactive({packageCode:'',packageName:'',processVersion:'',effectiveApprovedDate:'',description:''}),definition=reactive<RouteDefinition>(blankRoute()),error=ref(''),busy=ref(false),conflict=ref(false),tab=ref('forms'),workspaceTab=ref<'operations'|'products'>('operations'),lintResult=ref('尚未校验'),ruleTexts=ref<Record<string,string>>({})
const applicableProductIds=ref<string[]>([]),applicableProducts=ref<ApplicableProduct[]>([]),productOptions=ref<ApplicableProduct[]>([]),productPickerDraft=ref<string[]>([]),productSearch=ref(''),productPickerOpen=ref(false),productPickerBusy=ref(false)
let productPickerTrigger:HTMLElement|null=null
watch(productPickerOpen,async open=>{
 await nextTick()
 if(open){const input=document.querySelector<HTMLInputElement>('.ant-modal-wrap[role="dialog"] .ant-select-selection-search-input');input?.setAttribute('aria-labelledby','process-applicable-product-picker-label');input?.focus()}
 else productPickerTrigger?.focus()
})
const visibleProductOptions=computed(()=>{const keyword=productSearch.value.trim().toLowerCase();return productOptions.value.filter(p=>!keyword||p.productName.toLowerCase().includes(keyword)||p.productCode.toLowerCase().includes(keyword)||productPickerDraft.value.includes(p.id))})
const ebrDefinitions=ref<EbrDetail[]>([]),ebrBusy=ref(false),ebrError=ref(''),ebrLoaded=ref(false)
const savedOps=ref<string[]>([]),savedParams=ref<Record<string,string[]>>({})
let processRequest=0,ebrRequest=0
onBeforeUnmount(()=>{processRequest++;ebrRequest++})
let pendingBody='',pendingKey=idempotencyKey(),baseline=''
const basicInfo=reactive({packageName:'',processVersion:'',effectiveApprovedDate:'',description:''});let originalBasic=''
const authored=()=>JSON.stringify({basicInfo,productIds:applicableProductIds.value,definition:{routeCode:definition.routeCode,operations:definition.operations},rules:definition.operations.map(o=>o.completionRule)}),dirty=computed(()=>!!v.value&&authored()!==baseline)
function sync(){Object.assign(basicInfo,{packageName:pkg.value?.packageName??'',processVersion:pkg.value?.processVersion??'',effectiveApprovedDate:pkg.value?.effectiveApprovedDate??'',description:pkg.value?.description??''});originalBasic=JSON.stringify(basicInfo);applicableProductIds.value=[...(pkg.value?.productIds??pkg.value?.applicableProducts?.map(p=>p.id)??[])];applicableProducts.value=clone(pkg.value?.applicableProducts??[]);Object.assign(definition,clone(v.value?.route??blankRoute()));for(const op of definition.operations){op.ipcDefinitions??=[];op.predecessorCodes??=[];}selectedIndex.value=Math.max(0,definition.operations.findIndex(o=>o.operationCode===String(route.query.operationCode??'')));tab.value=String(route.query.section??'forms');workspaceTab.value='operations';savedOps.value=definition.operations.map(o=>o.operationCode);savedParams.value=Object.fromEntries(definition.operations.map(o=>[o.operationCode,o.parameters.map(p=>p.parameterCode)]));ruleTexts.value=Object.fromEntries(definition.operations.map(o=>[o.operationCode,o.completionRule?JSON.stringify(o.completionRule):'']));restoreSelection();baseline=authored();lintResult.value=v.value?.status==='EFFECTIVE'?'当前配置已生效':'配置尚未完整'}
function failure(e:unknown){let message=axios.isAxiosError(e)?errorMessage(e):(e as Error).message;if(axios.isAxiosError(e)&&e.response?.data?.code==='DUPLICATE_CODE')message='工艺编码已存在，请使用其他编码';if(message.startsWith('route.routeCode:'))message='请填写路线代码（最多64个字符）';error.value=message;conflict.value=axios.isAxiosError(e)&&e.response?.status===409&&e.response?.data?.code!=='DUPLICATE_CODE'}
watch(error,async message=>{if(message){await nextTick();document.getElementById('process-save-errors')?.focus()}})
const listQuery=computed(()=>Object.fromEntries(Object.entries(route.query).filter(([key])=>key!=='versionId')))
async function loadEbrDefinitions(){
 const packageId=pkg.value?.id,ticket=++ebrRequest
 const stale=()=>ticket!==ebrRequest||pkg.value?.id!==packageId
 ebrDefinitions.value=[];ebrError.value='';ebrLoaded.value=false
 if(!packageId||!auth.can('ebr:template:view'))return
 ebrBusy.value=true
 try{
  const items:EbrSummary[]=[];let pageNumber=0,total=0
  do{const page=await api<Page<EbrSummary>>({url:'/ebr/templates',params:{processPackageId:packageId,page:pageNumber,size:100}});if(stale())return;items.push(...page.items);total=page.total;if(!page.items.length&&items.length<total)throw Error('表单分页返回不完整，请重试');pageNumber++}while(items.length<total)
  const details:EbrDetail[]=[]
  for(const item of items){const detail=await api<EbrDetail>({url:`/ebr/templates/${item.id}`});if(stale())return;details.push(detail)}
  ebrDefinitions.value=details;ebrLoaded.value=true
 }catch(e){if(!stale())ebrError.value=axios.isAxiosError(e)?errorMessage(e):(e as Error).message}
 finally{if(!stale())ebrBusy.value=false}
}
async function loadProductOptions(){if(!auth.can('master:product:view'))return;productPickerBusy.value=true;try{const page=await api<Page<Product>>({url:'/products',params:{page:0,size:100,keyword:productSearch.value,status:'ACTIVE'}});const merged=new Map<string,ApplicableProduct>(productOptions.value.map(p=>[p.id,p]));for(const item of page.items)merged.set(item.id,{...item,productId:item.id});for(const item of applicableProducts.value)if(!merged.has(item.id))merged.set(item.id,item);productOptions.value=[...merged.values()]}catch(e){error.value=errorMessage(e)}finally{productPickerBusy.value=false}}
async function openProductPicker(){if(!editable.value||!auth.can('master:product:view'))return;productPickerTrigger=document.activeElement instanceof HTMLElement?document.activeElement:null;productPickerDraft.value=[...applicableProductIds.value];productSearch.value='';await loadProductOptions();productPickerOpen.value=true}
function searchProductOptions(value:string){productSearch.value=value;void loadProductOptions()}
function saveProductPicker(){const chosen=productPickerDraft.value.map(id=>productOptions.value.find(p=>p.id===id)??applicableProducts.value.find(p=>p.id===id)).filter((p):p is ApplicableProduct=>!!p);applicableProductIds.value=chosen.map(p=>p.id);applicableProducts.value=chosen;productPickerOpen.value=false}
function removeApplicableProduct(id:string){if(!editable.value)return;applicableProductIds.value=applicableProductIds.value.filter(x=>x!==id);applicableProducts.value=applicableProducts.value.filter(x=>x.id!==id)}
function formsForOperation(operationCode:string){
 return ebrDefinitions.value.flatMap(template=>template.definition.forms
  .filter(form=>template.operationChoices.find(choice=>choice.id===form.operationDefId)?.operationCode===operationCode)
  .map(form=>({template,form})))
}
function cppRuleCount(item:ReturnType<typeof formsForOperation>[number]){return (item.template.definition.rules??[]).filter(rule=>rule.formCode===item.form.formCode&&!!rule.cppConfigJson).length}
function formRowKey(item:ReturnType<typeof formsForOperation>[number]){return JSON.stringify([item.template.id,item.form.formCode])}
function rememberSelection(){if(pkg.value&&selected.value)sessionStorage.setItem(`process-workspace:${pkg.value.id}`,JSON.stringify({operationCode:selected.value.operationCode,section:tab.value,workspaceTab:workspaceTab.value}))}
function openEbrFormTemplate(id:string,formCode:string,designerTab:'form'|'cpp'='form'){if(dirty.value){error.value='请先保存当前工艺，再进入表单设计器';return}rememberSelection();void router.push({path:auth.can('ebr:template:update')?`/ebr/templates/${id}/designer`:`/ebr/templates/${id}`,query:{processPackageId:pkg.value?.id,formCode,designerTab,returnTo:`/process/packages/${pkg.value?.id}`}})}
function createEbrFormTemplate(){if(!pkg.value||dirty.value||!selected.value||!savedOps.value.includes(selected.value.operationCode))return;rememberSelection();void router.push({path:'/ebr/templates/create',query:{processPackageId:pkg.value.id,operationCode:selected.value.operationCode,initializeOperation:'1',formCode:selected.value.operationCode+'_RECORD',returnTo:`/process/packages/${pkg.value.id}`} })}
async function load(){const ticket=++processRequest;ebrRequest++;ebrBusy.value=false;error.value='';conflict.value=false;pkg.value=null;if(create.value)return;try{const loaded=await api<Package>({url:`/process-packages/${route.params.id}`});if(ticket!==processRequest)return;pkg.value=loaded;sync();await loadEbrDefinitions()}catch(e){if(ticket===processRequest)failure(e)}}
function headers(body:unknown){const encoded=JSON.stringify(body);if(encoded!==pendingBody){pendingBody=encoded;pendingKey=idempotencyKey()}return {'Idempotency-Key':pendingKey}}
function requiredReason(){return '工艺配置维护（系统记录）'}
async function createPackage(){busy.value=true;error.value='';try{const p=await api<Package>({url:'/process-packages',method:'POST',data:{...createForm,effectiveApprovedDate:createForm.effectiveApprovedDate||''},headers:headers(createForm)});pendingBody='';Object.assign(createForm,{packageCode:'',packageName:'',processVersion:'',effectiveApprovedDate:'',description:''});await router.push({path:`/process/packages/${p.id}/edit`,query:listQuery.value})}catch(e){failure(e)}finally{busy.value=false}}
function renameOperation(op:RouteDefinition['operations'][number],event:Event){const next=(event.target as HTMLInputElement).value;const old=op.operationCode;if(old!==next){ruleTexts.value[next]=ruleTexts.value[old]??'';delete ruleTexts.value[old];for(const other of definition.operations)other.predecessorCodes=other.predecessorCodes.map(c=>c===old?next:c);op.operationCode=next}}
function addOperation(){let n=definition.operations.length+1;while(definition.operations.some(o=>o.operationCode===`OP${n}`))n++;definition.operations.push({operationCode:`OP${n}`,operationName:'',sequenceNo:Math.max(0,...definition.operations.map(o=>o.sequenceNo))+1,requiredRole:null,completionRule:null,predecessorCodes:[],requiredEquipmentType:null,clearanceRequired:false,parameters:[]});selectedIndex.value=definition.operations.length-1;tab.value='operation'}
function validateRule(rule:unknown,depth=0):asserts rule is Rule{if(!rule||typeof rule!=='object'||Array.isArray(rule)||depth>=8)throw Error('完成规则格式或层级无效');const r=rule as Rule;if(['ALL','ANY'].includes(r.kind)){if(Object.keys(r).some(k=>!['kind','rules'].includes(k))||!Array.isArray(r.rules)||!r.rules.length||r.rules.length>20)throw Error('组合完成规则需要 1–20 个子规则');r.rules.forEach(c=>validateRule(c,depth+1))}else if(!['EBR_COMPLETE','PARAMETERS_WITHIN_LIMITS','REVIEW_COMPLETE'].includes(r.kind)||Object.keys(r).some(k=>k!=='kind'))throw Error('完成规则仅支持已定义的声明式类型')}
function routePayload(){return {routeCode:definition.routeCode,operations:definition.operations.map(o=>{const rule=o.completionRule;if(rule)validateRule(rule);return {...o,completionRule:rule}})}}
async function save(){busy.value=true;error.value='';try{if(JSON.stringify(basicInfo)!==originalBasic&&!basicInfo.packageName.trim())throw Error('请填写工艺名称');const body={route:routePayload(),productIds:[...applicableProductIds.value],...(JSON.stringify(basicInfo)!==originalBasic?{basicInfo:{packageName:basicInfo.packageName.trim(),description:basicInfo.description.trim()||'',processVersion:basicInfo.processVersion.trim(),effectiveApprovedDate:basicInfo.effectiveApprovedDate||''}}:{})};pkg.value=await api<Package>({url:`/process-packages/${pkg.value!.id}/current-definition`,method:'PUT',data:body,headers:headers(body)});pendingBody='';conflict.value=false;sync();lintResult.value='保存成功，配置已生效';await router.replace({path:`/process/packages/${pkg.value!.id}`,query:listQuery.value})}catch(e){failure(e)}finally{busy.value=false}}
async function disablePackage(){busy.value=true;error.value='';try{const body={reason:requiredReason(),action:'DISABLE'};await api({url:`/process-packages/${pkg.value!.id}`,method:'PUT',data:body,headers:headers(body)});pendingBody='';await load()}catch(e){failure(e)}finally{busy.value=false}}

const unsaved=computed(()=>create.value?Object.values(createForm).some(value=>value.length>0):dirty.value)
onBeforeRouteLeave(()=>!unsaved.value||window.confirm('离开页面将放弃未保存的修改，是否继续？'))
function beforeUnload(event:BeforeUnloadEvent){if(unsaved.value){event.preventDefault();event.returnValue=''}}
window.addEventListener('beforeunload',beforeUnload)
onBeforeUnmount(()=>window.removeEventListener('beforeunload',beforeUnload))
watch(()=>route.fullPath,load,{immediate:true})

const selectedIndex=ref(0),selected=computed(()=>definition.operations[selectedIndex.value]??null)
const itemDialog=ref(false),itemIndex=ref(-1),itemValue=ref<Parameter|null>(null)
const itemPersisted=computed(()=>itemValue.value!=null&&(savedParams.value[selected.value?.operationCode??'']??[]).includes(itemValue.value.parameterCode))
function selectOperation(i:number){selectedIndex.value=i}
function moveOperation(delta:number){const i=selectedIndex.value,j=i+delta;if(j<0||j>=definition.operations.length)return;[definition.operations[i],definition.operations[j]]=[definition.operations[j]!,definition.operations[i]!];definition.operations.forEach((o,k)=>o.sequenceNo=k+1);selectedIndex.value=j}
function copyOperation(){if(!selected.value)return;const copy:Operation=clone(selected.value);let n=definition.operations.length+1;while(definition.operations.some(o=>o.operationCode===`OP${n}`))n++;copy.operationCode=`OP${n}`;delete copy.operationType;delete copy.ipcDefinitions;copy.sequenceNo=definition.operations.length+1;definition.operations.push(copy);selectedIndex.value=definition.operations.length-1;tab.value='operation'}
function removeOperation(){const op=selected.value;if(!op||savedOps.value.includes(op.operationCode))return;if(definition.operations.some(o=>o.predecessorCodes.includes(op.operationCode))){error.value='请先解除引用该工序的前置关系';return}definition.operations.splice(selectedIndex.value,1);definition.operations.forEach((o,i)=>o.sequenceNo=i+1);selectedIndex.value=Math.max(0,selectedIndex.value-1)}
function editItem(index=-1){itemIndex.value=index;itemValue.value=index<0?null:clone(selected.value!.parameters[index]!);itemDialog.value=true}
function saveItem(value:Parameter|IpcDefinition){if(!selected.value||!('parameterCode' in value))return;if(selected.value.parameters.some((v,i)=>i!==itemIndex.value&&v.parameterCode===value.parameterCode)){error.value='编码已存在，请使用其他编码';return}if(itemIndex.value<0)selected.value.parameters.push(value);else selected.value.parameters[itemIndex.value]=value;itemDialog.value=false}
function keepFocusedVisible(e:Event){const target=e.target;if(!(target instanceof HTMLElement)||target.closest('.workspace-footer'))return;requestAnimationFrame(()=>{const footer=document.querySelector('.workspace-footer');if(footer&&target.getBoundingClientRect().bottom>footer.getBoundingClientRect().top-8&&typeof target.scrollIntoView==='function')target.scrollIntoView({block:'center'})})}
function reloadConfirmed(){if(!dirty.value||window.confirm('重新加载将放弃本地修改，是否继续？'))void load()}
function onWorkspaceTabKeydown(event:KeyboardEvent){
 const order:['operations','products']=['operations','products']
 const current=order.indexOf(workspaceTab.value)
 const next=event.key==='Home'?0:event.key==='End'?order.length-1:event.key==='ArrowRight'?(current+1)%order.length:event.key==='ArrowLeft'?(current+order.length-1)%order.length:-1
 if(next<0)return
 event.preventDefault()
 workspaceTab.value=order[next]!
 ;(event.currentTarget as HTMLElement).querySelectorAll<HTMLButtonElement>('[role="tab"]')[next]?.focus()
}
function restoreSelection(){try{const saved=JSON.parse(sessionStorage.getItem(`process-workspace:${pkg.value?.id}`)??'null');if(saved){selectedIndex.value=Math.max(0,definition.operations.findIndex(o=>o.operationCode===saved.operationCode));if(['operation','forms','parameters'].includes(saved.section))tab.value=saved.section;if(['operations','products'].includes(saved.workspaceTab))workspaceTab.value=saved.workspaceTab}}catch{/* Unavailable or obsolete view state must never prevent loading business data. */}}

</script>
<template><main :data-ui-template="create||editing?'T2':'T4'" class="admin-page master-page process-page" v-select-accessibility @focusin="keepFocusedVisible" @input="keepFocusedVisible">
<header class="admin-page-header"><h1>{{create?'新增生产工艺':editing?'编辑生产工艺':pkg?.packageName||pkg?.packageCode||'生产工艺'}}</h1><a-button v-if="!create&&!editing&&pkg?.status==='ACTIVE'&&auth.can('process:package:edit')" type="primary" @click="router.push({path:`/process/packages/${pkg.id}/edit`,query:listQuery})">编辑工艺</a-button></header>
<a-alert v-if="error" id="process-save-errors" tabindex="-1" type="error" :message="error" show-icon role="alert"/><a-alert v-if="conflict" type="warning" message="记录已发生变化，输入已保留。重新加载将放弃本地修改，请核对后继续。"><template #action><a-button @click="reloadConfirmed">重新加载</a-button></template></a-alert>
<a-card v-if="create" title="工艺基本信息"><form class="master-form" @submit.prevent="createPackage"><label><span class="form-field-label">工艺编码</span><input v-model="createForm.packageCode" class="master-native-input" :maxlength="64" required/></label><label><span class="form-field-label">工艺名称</span><a-input v-model:value="createForm.packageName" :maxlength="200" required/></label><label><span class="form-field-label">版本</span><a-input v-model:value="createForm.processVersion" :maxlength="32"/></label><label><span class="form-field-label">生效批准日期</span><a-input v-model:value="createForm.effectiveApprovedDate" type="date"/></label><label class="form-full-row"><span class="form-field-label">工艺说明</span><a-textarea v-model:value="createForm.description" :maxlength="1000"/></label><div class="form-full-row process-create-actions"><a-button type="primary" html-type="submit" :loading="busy" :disabled="!createForm.packageCode.trim()||!createForm.packageName.trim()">创建生产工艺</a-button><a-button @click="router.push('/process/packages')">取消</a-button></div></form></a-card>
<template v-else-if="pkg&&v"><a-card title="工艺基本信息" class="basic-card"><div class="master-form"><label><span class="form-field-label">工艺编码</span><a-input :value="pkg.packageCode" disabled/></label><label><span class="form-field-label">工艺名称</span><a-input v-model:value="basicInfo.packageName" :disabled="!editable" :placeholder="!editing&&!basicInfo.packageName?'未命名（历史工艺）':undefined" :maxlength="200"/></label><label><span class="form-field-label">版本</span><a-input v-model:value="basicInfo.processVersion" :disabled="!editable" :maxlength="32"/></label><label><span class="form-field-label">生效批准日期</span><a-input v-model:value="basicInfo.effectiveApprovedDate" :disabled="!editable" type="date"/></label><label><span class="form-field-label">路线代码</span><a-input v-model:value="definition.routeCode" :disabled="!editable" :maxlength="64"/></label><label><span class="form-field-label">启停状态</span><a-input :value="states[pkg.status]" disabled/></label><label><span class="form-field-label">配置状态</span><a-input :value="v.status==='EFFECTIVE'?'配置可用':'待完善'" disabled/></label><label class="form-full-row"><span class="form-field-label">工艺说明</span><a-textarea v-model:value="basicInfo.description" :disabled="!editable" :maxlength="1000"/></label></div></a-card>
<section class="workspace"><div class="workspace-heading"><div class="process-workspace-tabs" role="tablist" aria-label="生产工艺配置" @keydown="onWorkspaceTabKeydown"><button type="button" role="tab" :tabindex="workspaceTab==='operations'?0:-1" :aria-selected="workspaceTab==='operations'" :class="{active:workspaceTab==='operations'}" @click="workspaceTab='operations'">工序与记录表单</button><button type="button" role="tab" :tabindex="workspaceTab==='products'?0:-1" :aria-selected="workspaceTab==='products'" :class="{active:workspaceTab==='products'}" @click="workspaceTab='products'">适用产品 <span>{{applicableProductIds.length}}</span></button></div><a-button v-if="editable&&workspaceTab==='operations'" type="primary" @click="addOperation">＋ 添加工序</a-button></div>
<template v-if="workspaceTab==='operations'">
<div class="workspace-body"><aside class="operation-list"><strong>工序清单 <span>{{definition.operations.length}}</span></strong><button v-for="(op,i) in definition.operations" :key="i" :class="{active:i===selectedIndex}" :aria-pressed="i===selectedIndex" @click="selectOperation(i)"><b>{{String(op.sequenceNo).padStart(2,'0')}}</b><span><strong>{{op.operationName||'新工序'}}</strong><small>{{op.operationCode}}{{ebrLoaded?' · '+formsForOperation(op.operationCode).length+' 份表单':''}}</small></span></button><p v-if="!definition.operations.length">还没有工序</p></aside>
<div class="operation-detail"><template v-if="selected"><header class="operation-heading"><div><small>第 {{selectedIndex+1}} 道工序</small><h2>{{selected.operationCode}} · {{selected.operationName||'新工序'}}</h2></div><a-space v-if="editable" wrap><a-button :disabled="!selectedIndex" @click="moveOperation(-1)">上移</a-button><a-button :disabled="selectedIndex===definition.operations.length-1" @click="moveOperation(1)">下移</a-button><a-button @click="copyOperation">复制</a-button><a-button danger :disabled="savedOps.includes(selected.operationCode)" @click="removeOperation">移除</a-button></a-space></header>
<a-tabs v-model:active-key="tab"><a-tab-pane key="operation" tab="工序设置"><div class="operation-fields master-form"><label><span class="form-field-label">工序编码</span><a-input :value="selected.operationCode" @input="renameOperation(selected,$event)" :disabled="!editable||savedOps.includes(selected.operationCode)" :maxlength="64"/></label><label><span class="form-field-label">工序名称</span><a-input v-model:value="selected.operationName" :disabled="!editable" :maxlength="200"/></label><label><span class="form-field-label">前置工序</span><a-select v-model:value="selected.predecessorCodes" mode="multiple" :disabled="!editable" :options="definition.operations.filter(o=>o!==selected).map(o=>({value:o.operationCode,label:o.operationCode+' · '+o.operationName}))"/></label><label><span class="form-field-label">所需角色</span><a-input v-model:value="selected.requiredRole" :disabled="!editable" :maxlength="64"/></label><label><span class="form-field-label">设备类型</span><a-input v-model:value="selected.requiredEquipmentType" :disabled="!editable" :maxlength="64"/></label><label><span class="form-field-label">清场要求</span><a-checkbox v-model:checked="selected.clearanceRequired" :disabled="!editable">是</a-checkbox></label><div class="form-inline-row form-full-row"><span class="form-field-label">完成条件</span><CompletionRuleEditor v-model="selected.completionRule" :disabled="!editable"/></div></div></a-tab-pane>
<a-tab-pane key="forms" tab="工序表单"><template v-if="auth.can('ebr:template:view')"><div class="process-form-toolbar">
 <div><strong>工序表单</strong><p>每道生产工序可配置一份或多份表单；表单使用 Canvas Editor 设计，生产执行时按工序自动带出。</p></div>
 <a-button v-if="auth.can('ebr:template:create')" type="primary" :disabled="pkg.status!=='ACTIVE'||ebrBusy||!ebrLoaded||dirty||!selected||!savedOps.includes(selected.operationCode)" @click="createEbrFormTemplate">＋ 新建工序表单</a-button>
</div>
<a-alert v-if="ebrError" type="error" :message="`工序表单加载失败：${ebrError}`" show-icon><template #action><a-button @click="loadEbrDefinitions">重试加载工序表单</a-button></template></a-alert>
<p v-if="ebrBusy" role="status">正在加载工序表单…</p>
<a-spin :spinning="ebrBusy">
 <a-empty v-if="!definition.operations.length" description="请先在工艺路线中维护生产工序"/>
 <a-card v-if="selected" :title="selected.operationCode+' · '+selected.operationName" class="process-operation process-form-card">
  <template #extra><a-tag v-if="ebrLoaded">{{formsForOperation(selected.operationCode).length}} 份表单</a-tag><a-tag v-else>{{ebrBusy?'加载中':'加载失败'}}</a-tag></template>
  <a-table :data-source="formsForOperation(selected.operationCode)" :row-key="formRowKey" :pagination="false" :scroll="{x:980}" size="small">
   <a-table-column title="表单名称" width="220"><template #default="{record:item}"><strong>{{item.form.formName}}</strong></template></a-table-column>
   <a-table-column title="表单编码" width="160"><template #default="{record:item}">{{item.form.formCode}}</template></a-table-column>
   <a-table-column title="所属模板" width="240"><template #default="{record:item}"><div class="process-template-source">{{item.template.templateName||'未命名（历史模板）'}}</div><small class="process-template-source">{{item.template.templateCode}}</small></template></a-table-column>
   <a-table-column title="模板版本" width="150"><template #default="{record:item}">V{{item.template.version}} · {{states[item.template.status]??item.template.status}}</template></a-table-column>
   <a-table-column title="字段数" width="90"><template #default="{record:item}">{{item.form.fields.length}}</template></a-table-column>
   <a-table-column title="CPP规则" width="100"><template #default="{record:item}">{{cppRuleCount(item)}} 条</template></a-table-column>
   <a-table-column title="操作" width="250" fixed="right"><template #default="{record:item}"><a-button type="link" @click="openEbrFormTemplate(item.template.id,item.form.formCode,'form')">{{auth.can('ebr:template:update')&&item.template.status==='DRAFT'?'设计表单':'查看表单'}}</a-button><a-button type="link" @click="openEbrFormTemplate(item.template.id,item.form.formCode,'cpp')">{{auth.can('ebr:template:update')&&item.template.status==='DRAFT'?'定义CPP规则':'查看CPP规则'}}</a-button></template></a-table-column>
   <template #emptyText><a-empty :image="false" :description="ebrLoaded?'该工序尚未配置表单':ebrBusy?'正在加载工序表单':'工序表单尚未加载成功，请重试'"/></template>
  </a-table>
 </a-card>
</a-spin></template><a-alert v-else type="info" message="无工序表单查看权限" show-icon/></a-tab-pane>
<a-tab-pane key="parameters" tab="工艺参数"><div class="item-section"><header><strong>工艺参数</strong><a-button v-if="editable" type="primary" @click="editItem()">新增参数</a-button></header><a-table :data-source="selected.parameters" row-key="parameterCode" :pagination="false" :scroll="{x:600}"><a-table-column title="编码" data-index="parameterCode"/><a-table-column title="名称" data-index="parameterName"/><a-table-column title="范围"><template #default="{record}">{{record.lowerLimit??'—'}} ～ {{record.upperLimit??'—'}}</template></a-table-column><a-table-column title="操作" :width="90" fixed="right"><template #default="{index}"><a-button v-if="editable" type="link" @click="editItem(index)">编辑</a-button></template></a-table-column><template #emptyText>当前工序尚未配置工艺参数</template></a-table></div></a-tab-pane></a-tabs></template><a-empty v-else description="当前工艺尚未维护工序"/></div></div></template><div v-else class="product-scope-panel"><header class="product-scope-heading"><div><strong>适用产品</strong><p>一套生产工艺可以关联多个产品；产品通过工艺间接使用相同的工序与 EBR 表单。</p></div><a-button v-if="editable&&auth.can('master:product:view')" type="primary" @click="openProductPicker">＋ 选择产品</a-button></header><a-empty v-if="!applicableProducts.length" description="当前工艺尚未指定适用产品，可作为通用工艺使用"/><div v-else class="applicable-product-grid"><article v-for="product in applicableProducts" :key="product.id" class="applicable-product-card"><header><a-tag color="blue">适用产品</a-tag><a-button v-if="editable" type="link" danger @click="removeApplicableProduct(product.id)">移除</a-button></header><strong>{{product.productName}}</strong><dl><div><dt>产品编码</dt><dd>{{product.productCode}}</dd></div><div><dt>规格</dt><dd>{{product.specification||'—'}}</dd></div><div><dt>剂型</dt><dd>{{product.dosageForm||'—'}}</dd></div><div><dt>状态</dt><dd>{{states[product.status]||product.status}}</dd></div></dl></article></div></div></section>
<a-modal v-model:open="productPickerOpen" title="选择适用产品" centered :width="760" :confirm-loading="productPickerBusy"><div v-select-accessibility class="product-picker"><p>可多选适用产品；停用产品仅保留已关联关系，不可新增关联。</p><label class="product-picker-label"><span id="process-applicable-product-picker-label" class="form-field-label">适用产品</span><a-select v-model:value="productPickerDraft" mode="multiple" show-search :filter-option="false" :options="visibleProductOptions.map(p=>({value:p.id,label:p.productName+'（'+p.productCode+'）',disabled:p.status!=='ACTIVE'&&!applicableProductIds.includes(p.id)}))" placeholder="搜索并选择产品" style="width:100%" @search="searchProductOptions"/></label><div class="product-picker-count">已选择 {{productPickerDraft.length}} 个产品</div></div><template #footer><a-button type="primary" :loading="productPickerBusy" @click="saveProductPicker">确认</a-button><a-button @click="productPickerOpen=false">取消</a-button></template></a-modal><footer class="workspace-footer"><span role="status" aria-live="polite" aria-atomic="true">{{dirty?'有未保存的修改':lintResult}}</span><a-space><a-button v-if="editing&&auth.can('process:package:edit')&&pkg.status==='ACTIVE'" type="primary" :loading="busy" :disabled="conflict" @click="save">保存并生效</a-button><a-button :disabled="busy" @click="router.push({path:editing?`/process/packages/${pkg.id}`:'/process/packages',query:listQuery})">{{editing?'取消':'返回列表'}}</a-button><a-button v-if="!editing&&pkg.status==='ACTIVE'&&auth.can('process:package:update')" danger :disabled="busy" @click="disablePackage">停用生产工艺</a-button></a-space></footer>
</template><OperationItemDialog :open="itemDialog" kind="PARAMETER" :value="itemValue" :persisted="itemPersisted" @cancel="itemDialog=false" @save="saveItem"/></main></template>
